export function detectMarkdown(t){if(!t||"string"!=typeof t)return!1;let r,s=t;do{r=s,s=s.replace(/<[^<>]*>/g,"")}while(s!==r);const o=s.trim(),e=[/^#{1,6}\s+.+$/m,/^```[\s\S]*?```$/m,/^\|.+\|.+\|.*$/m,/^>\s+.+$/m,/^\s*\*{3,}\s*$/m,/^\s*-{3,}\s*$/m,/^\s*_{3,}\s*$/m];for(const t of e)if(t.test(o))return!0;const n=[/^\s*[-*+]\s+.+$/m,/^\s*\d+\.\s+.+$/m,/\*\*[^*]+\*\*/,/(?<!\*)\*[^*]+\*(?!\*)/,/\[.+?\]\(.+?\)/,/!\[.*?\]\(.+?\)/,/`[^`\n]+`/,/^\s{4,}.+$/m];let a=0;for(const t of n)t.test(o)&&a++;return a>=2}export async function markdownToHTML(t){try{const r=await(import("./marked.js")),{marked:s}=r;return s.parse(t)}catch(r){return console.warn("Failed to parse markdown, falling back to original text:",r),t}}